		if err != nil {
			break
		}
		lines = append(lines, line)
	}

	if len(lines) == 0 {
		return
	}

	// Remove trailing newline from the last line if present
	for i := range lines {
		lines[i] = strings.TrimRight(lines[i], "\n")
	}

	if len(lines) == 0 {
		return
	}

	firstLine := lines[0]
	rest := lines[1:]

	parts := strings.Split(firstLine, " ")
	if len(parts) < 2 {
		return
	}

	v, _ := strconv.Atoi(parts[0])
	e, _ := strconv.Atoi(parts[1])

	if e == 0 {
		fmt.Println(0)
		return
	}

	if v <= 6 {
		fmt.Println(e)
		return
	}

	// Build adjacency list
	adj := make(map[int][]int)
	for i := 1; i <= v; i++ {
		adj[i] = []int{}
	}

	for i := 0; i < e && i < len(rest); i++ {
		edgeParts := strings.Split(rest[i], " ")
		if len(edgeParts) < 2 {
			continue
		}
