			for _, val := range other {
				otherSet[val] = true
			}
			x := []int{}
			for _, val := range a7 {
				if otherSet[val] {
					x = append(x, val)
				}
			}
			if len(x) == 0 {
				f = true
				break
			} else if len(x) < noOfVertices {
				noOfVertices = len(x)
			}
		}
		if f {
			break
		}
	}

	if f {
		fmt.Println(e)
	} else {
		fmt.Println(e - noOfVertices)
	}
}
